// Local reference walking routes follow mapped OSM roads, never a straight line through buildings.
const rad=d=>d*Math.PI/180;
const pair=p=>Array.isArray(p)?p:[p.lng,p.lat];
export function distance(a,b){a=pair(a);b=pair(b);const dlat=rad(b[1]-a[1]),dlng=rad(b[0]-a[0]);return 6371000*2*Math.asin(Math.min(1,Math.sqrt(Math.sin(dlat/2)**2+Math.cos(rad(a[1]))*Math.cos(rad(b[1]))*Math.sin(dlng/2)**2)));}
export function direction(a,b){a=pair(a);b=pair(b);const y=Math.sin(rad(b[0]-a[0]))*Math.cos(rad(b[1])),x=Math.cos(rad(a[1]))*Math.sin(rad(b[1]))-Math.sin(rad(a[1]))*Math.cos(rad(b[1]))*Math.cos(rad(b[0]-a[0]));const bearing=(Math.atan2(y,x)*180/Math.PI+360)%360;return {bearing,name:['北','东北','东','东南','南','西南','西','西北'][Math.round(bearing/45)%8]};}
export const meters=n=>n>=1000?(n/1000).toFixed(1)+' 公里':Math.round(n)+' 米';
export function navigationURL(target,origin){const url=new URL('https://api.map.baidu.com/direction');url.search=new URLSearchParams({origin:origin?`latlng:${origin.lat.toFixed(6)},${origin.lng.toFixed(6)}|name:当前位置`:'我的位置',destination:`latlng:${target.lat.toFixed(6)},${target.lng.toFixed(6)}|name:${target.name}`,mode:'walking',region:'银川',output:'html',coord_type:'wgs84',src:'webapp.exploreshoots.campus'});return url.href;}
export function roadGraph(geo){const nodes=new Map(),edges=[];const id=c=>c.map(x=>x.toFixed(7)).join(',');const get=c=>{const key=id(c);if(!nodes.has(key))nodes.set(key,{key,c,links:[]});return nodes.get(key);};for(const f of geo.features||[]){if(f.geometry?.type!=='LineString'||!['residential','footway','path','pedestrian','service','living_street','track','steps'].includes(f.properties?.kind))continue;const cs=f.geometry.coordinates;for(let i=1;i<cs.length;i++){const a=get(cs[i-1]),b=get(cs[i]),length=distance(a.c,b.c);if(!length)continue;a.links.push({to:b.key,length});b.links.push({to:a.key,length});edges.push({a,b,length});}}return {nodes,edges};}
function snap(p,graph){p=pair(p);const scale=Math.cos(rad(p[1]));let best;for(const edge of graph.edges){const a=edge.a.c,b=edge.b.c,x=(b[0]-a[0])*scale,y=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*scale*x+(p[1]-a[1])*y)/(x*x+y*y)));const c=[a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])],gap=distance(p,c);if(!best||gap<best.gap)best={edge,c,t,gap};}return best;}
export function walkingLeg(graph,start,end){const a=snap(start,graph),b=snap(end,graph);if(!a||!b||a.gap>250||b.gap>250)return {available:false,reason:'点位附近缺少可用道路资料'};const costs=new Map(),prev=new Map(),pending=new Set(graph.nodes.keys());for(const [key,len] of [[a.edge.a.key,a.edge.length*a.t],[a.edge.b.key,a.edge.length*(1-a.t)]])costs.set(key,len);while(pending.size){let current,min=Infinity;for(const key of pending){const cost=costs.get(key)??Infinity;if(cost<min){current=key;min=cost;}}if(!current)break;pending.delete(current);for(const link of graph.nodes.get(current).links){if(!pending.has(link.to))continue;const next=min+link.length;if(next<(costs.get(link.to)??Infinity)){costs.set(link.to,next);prev.set(link.to,current);}}}let target,length=Infinity;for(const [key,extra] of [[b.edge.a.key,b.edge.length*b.t],[b.edge.b.key,b.edge.length*(1-b.t)]]){const total=(costs.get(key)??Infinity)+extra;if(total<length){length=total;target=key;}}let path;if(a.edge===b.edge&&a.edge.length*Math.abs(a.t-b.t)<=length){length=a.edge.length*Math.abs(a.t-b.t);path=[a.c,b.c];}else if(target){const keys=[];for(let k=target;k;k=prev.get(k))keys.unshift(k);path=[a.c,...keys.map(k=>graph.nodes.get(k).c),b.c];}if(!path)return {available:false,reason:'已知道路没有连通，请使用地图导航'};return {available:true,path,connectors:[[pair(start),a.c],[b.c,pair(end)]],length,lengthWithApproach:length+a.gap+b.gap,approach:a.gap+b.gap};}
export function walkingRoute(graph,stops){const legs=[];for(let i=1;i<stops.length;i++)legs.push({...walkingLeg(graph,stops[i-1],stops[i]),from:stops[i-1].id,to:stops[i].id});return {legs,missing:legs.filter(l=>!l.available).length,length:legs.filter(l=>l.available).reduce((n,l)=>n+l.lengthWithApproach,0)};}
